src='''def transform(grid):
    bg = grid[0][0]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for i in range(h):
        cols = [j for j in range(w) if grid[i][j] != bg]
        for a, b in zip(cols, cols[1:]):
            if b - a > 1:
                for j in range(a + 1, b):
                    if out[i][j] == bg:
                        out[i][j] = 3
    for j in range(w):
        rows = [i for i in range(h) if grid[i][j] != bg]
        for a, b in zip(rows, rows[1:]):
            if b - a > 1:
                for i in range(a + 1, b):
                    if out[i][j] == bg:
                        out[i][j] = 3
    return out
'''
open(base+'/task-6f47cfde.py','w').write(src)
